```latex
\documentclass{article}
\usepackage{amsmath,amssymb}
\begin{document}

\section*{VRPHTW: Compact Two-Index Arc Formulation with Commodity Flows}

\subsection*{Sets}
\begin{align*}
C &= \{1,\dots,n\}, \quad n=100 &&\text{(customers)}\\
D &= C \cup \{0\} &&\text{(nodes, depot }0\text{)}\\
V &= \{1,\dots,K\}, \quad K=25 &&\text{(vehicles)}\\
A &= \{(i,j)\in D\times D : i\neq j\} &&\text{(arcs)}
\end{align*}

\subsection*{Parameters}
\begin{align*}
q_i &\in \mathbb{Z}_+ &&\text{demand of customer }i,\; q_0=0,\;\sum_{i\in C}q_i=1721\\
[e_i,l_i] &&&\text{time window at }i,\; e_0=0,\;l_0=H\\
s_i &\in \mathbb{Z}_+ &&\text{service time at }i,\; s_0=0\\
d_{ij} &\in \mathbb{Z}_+ &&\text{Euclidean travel distance (truncated) from }i\text{ to }j\\
Q &= 200 &&\text{vehicle capacity}\\
H &= 230 &&\text{planning horizon (big-}M\text{ for time)}\\
c &\in \mathbb{R}_+ &&\text{fixed cost per vehicle (default }c=0\text{)}\\
\text{Depot} &: (35,35) &&\\
\text{Stats} &: |C|=100,\;\sum q_i=1721,\;K=25,\;Q=200,\;H=230 &&
\end{align*}

\noindent\textbf{Input file column mapping:} (1) Customer ID, (2) $x$-coordinate, (3) $y$-coordinate, (4) $q_i$, (5) $e_i$, (6) $l_i$, (7) $s_i$. Distances $d_{ij}=\lfloor\sqrt{(x_i-x_j)^2+(y_i-y_j)^2}\rceil$.

\subsection*{Variables}
\begin{align*}
x_{ij} &\in \{0,1\} &&\forall (i,j)\in A &&\text{arc }(i,j)\text{ is used by some vehicle}\\
y_k &\in \{0,1\} &&\forall k\in V &&\text{vehicle }k\text{ is used}\\
u_i &\in [e_i,l_i] &&\forall i\in D &&\text{service start time at }i\\
f_{ij} &\in \mathbb{Z}_+ &&\forall (i,j)\in A &&\text{number of vehicles traversing arc }(i,j)\\
g_{ij} &\in \mathbb{R}_+ &&\forall (i,j)\in A &&\text{load on arc }(i,j)\text{ (before service at }j\text{)}
\end{align*}

\subsection*{Objective}
\[
\min\;\; \sum_{(i,j)\in A} d_{ij}\,x_{ij} \;+\; c\sum_{k\in V} y_k
\]
(Default $c=0$ gives pure distance minimization.)

\subsection*{Constraints}

\paragraph{(1) Customer degree (each customer served exactly once):}
\begin{align}
\sum_{j\in D,\,j\neq i} x_{ij} &= 1 &&\forall i\in C \label{c:deg-out}\\
\sum_{i\in D,\,i\neq j} x_{ij} &= 1 &&\forall j\in C \label{c:deg-in}
\end{align}

\paragraph{(2) Depot degree equals number of vehicles used:}
\begin{align}
\sum_{j\in C} x_{0j} &= \sum_{k\in V} y_k \label{c:dep-out}\\
\sum_{i\in C} x_{i0} &= \sum_{k\in V} y_k \label{c:dep-in}
\end{align}

\paragraph{(3) Vehicle-count commodity flow (subtour elimination / route counting):}
\begin{align}
x_{ij} \le f_{ij} &\le K\,x_{ij} &&\forall (i,j)\in A \label{c:f-link}\\
\sum_{i\in D,\,i\neq j} f_{ij} - \sum_{i\in D,\,i\neq j} f_{ji} &= 0 &&\forall j\in C \label{c:f-cons}\\
\sum_{j\in C} f_{0j} - \sum_{j\in C} f_{j0} &= 0 \label{c:f-depot}\\
\sum_{j\in C} f_{0j} &= \sum_{k\in V} y_k \label{c:f-count}
\end{align}

\paragraph{(4) Time windows and MTZ time propagation:}
\begin{align}
u_0 &= 0 \label{c:u0}\\
e_i \le u_i &\le l_i &&\forall i\in D \label{c:tw}\\
u_j &\ge u_i + s_i + d_{ij} - H(1-x_{ij}) &&\forall (i,j)\in A,\; i\neq 0 \label{c:mtz}\\
u_i + s_i + d_{i0} &\le H - H(1-x_{i0}) &&\forall i\in C \label{c:return}
\end{align}

\paragraph{(5) Capacity via load commodity flow:}
\begin{align}
g_{ij} &\le Q\,x_{ij} &&\forall (i,j)\in A \label{c:g-cap}\\
\sum_{i\in D,\,i\neq j} g_{ij} - \sum_{i\in D,\,i\neq j} g_{ji} &= q_j &&\forall j\in C \label{c:g-cons}\\
\sum_{j\in C} g_{0j} &= \sum_{i\in C} q_i \label{c:g-depot-out}\\
\sum_{j\in C} g_{j0} &= 0 \label{c:g-depot-in}
\end{align}

\paragraph{(6) Symmetry breaking on vehicles:}
\begin{equation}
y_k \ge y_{k+1} \qquad \forall k=1,\dots,K-1 \label{c:sym}
\end{equation}

\subsection*{Correctness Argument (Equivalence)}
\begin{itemize}
\item \textbf{Feasibility of routing:} Constraints \eqref{c:deg-out}--\eqref{c:dep-in} force every customer to have in-degree 1 and out-degree 1, and the depot to have out-degree and in-degree equal to the number of used vehicles $R=\sum_k y_k$. Together with \eqref{c:f-link}--\eqref{c:f-count}, the $f$-flow is a circulation of value $R$ supported on the $x$-arcs, which decomposes into exactly $R$ vehicle routes starting and ending at the depot.
\item \textbf{Subtour elimination:} With hard time windows and $u_0=0$, the MTZ constraints \eqref{c:mtz}--\eqref{c:return} are exact: any subtour not containing the depot would have no anchor to $u_0=0$, and the propagation $u_j\ge u_i+s_i+d_{ij}$ forces a strictly increasing time along any directed cycle, which is infeasible since $u_0=0$ is both start and end. Hence subtours are impossible. (The $f$-flow provides a redundant, solver-friendly certificate.)
\item \textbf{Time windows:} \eqref{c:tw} enforces $[e_i,l_i]$; \eqref{c:mtz} propagates earliest feasible arrival; \eqref{c:return} ensures return-to-depot by $H$.
\item \textbf{Capacity:} The $g$-flow is a standard delivery commodity flow: at each customer $j$, load decreases by exactly $q_j$ (\eqref{c:g-cons}); the depot sources total demand \eqref{c:g-depot-out} and sinks zero \eqref{c:g-depot-in}; \eqref{c:g-cap} caps arc load by $Q$ whenever the arc is used. Hence every route respects capacity.
\item \textbf{Vehicle count:} \eqref{c:f-count} ties the number of routes to $\sum_k y_k$; \eqref{c:sym} removes symmetric permutations of identical vehicles.
\end{itemize}

\subsection*{Solving Notes}
The model has $O(|D|^2)=O(101^2)\approx 10^4$ binary $x_{ij}$, $K=25$ binary $y_k$, $|D|=101$ continuous $u_i$, $O(|D|^2)$ continuous $g_{ij}$, and $O(|D|^2)$ integer (relaxable) $f_{ij}$. It is solvable directly by branch-and-cut in a modern MILP solver (CPLEX, Gurobi, HiGHS). For larger instances, the $x_{ij}$ set can be restricted to feasible arcs (e.g., $e_i+s_i+d_{ij}\le l_j$) and a branch-and-price / column-generation approach can be applied on the $x$-variables.

\end{document}
```

